// Construct an MFRC522 object without touching hardware; initialization must be done later via PCD_Init().
MFRC522 *mfrc522 = new MFRC522();
// Track device state for downstream stubs: not initialized, antenna off, and not in power-down.
FUZZ_SET_ATTR_INT(mfrc522, "initialized", 0);
FUZZ_SET_ATTR_INT(mfrc522, "antenna_on", 0);
FUZZ_SET_ATTR_INT(mfrc522, "powered_down", 0);
// Validation: Constructor performs no I/O; we simply return a live object with attributes set for future checks.

// Preconditions: reader must be initialized and antenna on
if (FUZZ_GET_ATTR_INT(mfrc522, "initialized") == 0) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(mfrc522, "antenna_on") == 0) { FUZZ_BAIL(); }
// Prepare a temporary UID container. validBits in range 0..7
MFRC522::Uid tmpUid; tmpUid.size = 0; tmpUid.sak = 0; for (int i=0;i<10;i++) tmpUid.uidByte[i]=0;
byte validBits = (byte)(*FUZZ_PARAM(unsigned int) % 8);
// Invoke selection
MFRC522::StatusCode st = mfrc522->PICC_Select(&tmpUid, validBits);
if (st != MFRC522::STATUS_OK) { FUZZ_BAIL(); }
// On success, track selection state and UID metadata for downstream ops
FUZZ_SET_ATTR_INT(mfrc522, "card_selected", 1);
FUZZ_SET_ATTR_INT(mfrc522, "uid_size", (int)tmpUid.size);
FUZZ_SET_ATTR_INT(mfrc522, "sak", (int)tmpUid.sak);
// Keep the device alive by returning it as an output

// Preconditions: initialized, antenna on, and a card was previously selected
if (FUZZ_GET_ATTR_INT(mfrc522, "initialized") == 0) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(mfrc522, "antenna_on") == 0) { FUZZ_BAIL(); }
if (FUZZ_GET_ATTR_INT(mfrc522, "card_selected") == 0) { FUZZ_BAIL(); }
// Send HALT
MFRC522::StatusCode st = mfrc522->PICC_HaltA();
if (st != MFRC522::STATUS_OK) { FUZZ_BAIL(); }
// Clear selection state after successful HALT
FUZZ_SET_ATTR_INT(mfrc522, "card_selected", 0);
FUZZ_SET_ATTR_INT(mfrc522, "authenticated", 0);

// Preconditions: initialized, antenna on, and a card selected
